head.script:
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_1___input').value == '12:10';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_1___input').value == '11:10';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 dateIncrementType 을 확인한다.
    //1. In the Source tab, check the dateIncrementType.
    //Verify step 1. dateIncrementType="hour" 
    //1. dateIncrementType = "hour"
    //Test step 2. dataType 을 확인한다.
    //2. Check the dataType.
    //Verify step 2. dataType="time" 
    //2. dataType = "time"
    //Test step 3. increment 를 확인한다.
    //3. Check increment.
    //Verify step 3. increment="1"
    //3. increment = "1"
    //Test step 4. 브라우저에서 1210 (예제) 를 입력하고 엔터키를 입력한다.
    //4. In the browser, type 1210 (example) and press Enter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1___input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1___input').setValue('1210')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1___input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 12:10 데이터가 입력된다.
    //4. Data is input at 12:10.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    //Test step 5. 옆에 ▲ ▼ 버튼을 클릭한다.
    //5. Click the ▲ ▼ button next to it.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_downButton').click()");
    //Verify step 5. ▲ ▼ 버튼에 맞춰서 시간이 증가되고 감소된다.
    //5. The time is increased and decreased in accordance with the ▲ ▼ buttons.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
